import requests, json, os, time, hashlib
os.makedirs("raw_api", exist_ok=True)
BASE = "https://canapi.iarc.who.int/api/nordcan/v2/961"
COUNTRIES = "246_752_578_208"
CANCERS = {160:"Lung", 130:"Pancreas", 110:"Liver"}
SEXES = {1:"Male", 2:"Female"}
raw = {}
manifest = []
for c in CANCERS:
    for s in SEXES:
        u = f"{BASE}/survival/population/5/{s}/{COUNTRIES}/{c}/"
        p = {"surv_period":5,"age_surv":0,"year_start":1973,"year_end":2023}
        rr = requests.get(u, params=p, timeout=60)
        fn = f"raw_api/survival_cancer{c}_sex{s}.json"
        with open(fn,"w") as f: f.write(rr.text)
        j = rr.json()
        raw[(c,s)] = j
        manifest.append({"cancer":c,"cancer_label":CANCERS[c],"sex":s,"sex_label":SEXES[s],
                         "url":rr.url,"status":rr.status_code,"n_records":len(j.get("dataset",[])),
                         "top_keys":sorted(j.keys()),"file":fn,
                         "sha256":hashlib.sha256(rr.text.encode()).hexdigest()[:16]})
        time.sleep(0.3)
for m in manifest: print(m["cancer_label"], m["sex_label"], m["status"], m["n_records"], m["top_keys"])

